#include <Arduino.h>

const int LIGHT_THRESHOLD = 700;
const float TEMPERATURE_THRESHOLD_C = 50.0f;
unsigned long lastReport = 0;

void setup() {
  pinMode(A0, INPUT);
  pinMode(A1, INPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  lastReport = millis();
}

void loop() {
  int light = analogRead(A0);
  float temperatureC = analogRead(A1) * (500.0f / 1023.0f);
  bool alarm = light > LIGHT_THRESHOLD || temperatureC > TEMPERATURE_THRESHOLD_C;
  digitalWrite(13, alarm ? HIGH : LOW);
  unsigned long now = millis();
  if (now - lastReport >= 1000UL) {
    lastReport += 1000UL;
    Serial.print("Light: ");
    Serial.print(light);
    Serial.print(" Temperature C: ");
    Serial.println(temperatureC, 2);
    if (alarm) Serial.println("WARNING");
  }
}
